//! N8 conditionally-bounded bridge checks.
//!
//! The fixture is generated by `fock_sirk/examples/sm_defect_bridge.rs` and
//! binds the actual `finite_fixture` terms. Arithmetic endpoints are directed,
//! `HV` and `G = V*HV` are enclosed, and the spectral growth is Gershgorin-bounded,
//! but the Padé witness is not enclosed, so the overall status must stay
//! `conditionally-bounded`.

use fock_sirk::sm_bridge::{BridgeError, bind_artifact, sha256_hex, verify_bridge};
use fock_sirk::sm_defect::{
    CertificateHashes, Interval, finite_fixture, finite_fixture_bridge, finite_fixture_inputs,
    full_images_enclosure, reduced_generator_enclosure, reduced_growth, verify_certificate,
};
use serde_json::{Value, json};

const FIXTURE: &str = include_str!("../../docs/fixtures/sm_defect_bridge.json");
const LEAN_SOURCE: &str = include_str!("../lean/SmDefectSkew.lean");

/// Parse the exact rational H cells from `SmDefectSkew.lean`.
fn lean_matrix() -> Vec<Vec<(i64, i64, bool)>> {
    let after_def = LEAN_SOURCE
        .split_once("def H")
        .expect("SmDefectSkew.lean must define H")
        .1;
    let start = after_def.find("!![").expect("H must use matrix notation") + 3;
    let end = after_def[start..]
        .find(']')
        .expect("H matrix notation must close")
        + start;
    let matrix = &after_def[start..end];

    matrix
        .split(';')
        .map(|row| row.split(',').map(parse_lean_cell).collect())
        .collect()
}

fn parse_lean_cell(cell: &str) -> (i64, i64, bool) {
    let mut cell = cell.trim();
    let imaginary = match cell.strip_suffix("* Complex.I") {
        Some(rest) => {
            cell = rest.trim();
            true
        }
        None => false,
    };
    let cell = cell
        .strip_prefix('(')
        .and_then(|rest| rest.strip_suffix(')'))
        .unwrap_or(cell)
        .split(':')
        .next()
        .unwrap()
        .trim();
    let (numerator, denominator) = cell.split_once('/').map_or((cell, "1"), |(n, d)| (n, d));
    (
        numerator.trim().parse().unwrap(),
        denominator.trim().parse().unwrap(),
        imaginary,
    )
}

#[test]
fn fixture_is_regenerated_from_the_actual_finite_fixture() {
    let pinned: Value = serde_json::from_str(FIXTURE).unwrap();
    let regenerated = finite_fixture_bridge(0.2);
    assert_eq!(pinned, regenerated, "regenerate with sm_defect_bridge");
    verify_bridge(&pinned).unwrap();

    assert_eq!(pinned["status"], "conditionally-bounded");
    assert_eq!(pinned["theorem"]["proof_status"], "not-run");
    assert_eq!(
        pinned["finite_endpoint_proof"]["proof_status"],
        "kernel-verified"
    );
    assert_eq!(
        pinned["finite_endpoint_proof"]["payload_sha256"],
        sha256_hex(include_bytes!("../../docs/fixtures/sm_defect_proof.ndjson"))
    );
    assert!(
        pinned["theorem"]["remaining"]
            .as_str()
            .unwrap()
            .contains("open")
    );
    let analytic = &pinned["analytic_defect_proof"];
    assert_eq!(analytic["proof_status"], "kernel-verified");
    assert_eq!(analytic["declarations"], 38336);
    assert_eq!(
        analytic["compressed_payload_sha256"],
        sha256_hex(include_bytes!(
            "../../docs/fixtures/sm_defect_analytic_proof.ndjson.gz"
        ))
    );
    let skew = &pinned["matrix_skew_proof"];
    assert_eq!(skew["lean_name"], "BookProof.Sm.ChapterSmDefectSkew.A_skew");
    assert_eq!(skew["proof_status"], "kernel-verified");
    assert_eq!(skew["declarations"], 7540);
    assert_eq!(
        skew["compressed_payload_sha256"],
        sha256_hex(include_bytes!(
            "../../docs/fixtures/sm_defect_skew_proof.ndjson.gz"
        ))
    );
    assert_eq!(
        skew["source_sha256"],
        sha256_hex(include_bytes!("../lean/SmDefectSkew.lean"))
    );
    assert_eq!(skew["fixture_provenance"]["status"], "test-checked");
    assert_eq!(pinned["artifact"]["rounding"]["directed"], true);
    assert_eq!(
        pinned["artifact"]["rounding"]["spectral_growth_directed"],
        true
    );
    assert_eq!(
        pinned["artifact"]["rounding"]["spectral_input_enclosed"],
        true
    );
    assert_eq!(pinned["artifact"]["rounding"]["full_images_enclosed"], true);
    assert_eq!(
        pinned["artifact"]["rounding"]["pade_exponential_directed"],
        false
    );
    assert_eq!(pinned["artifact"]["measured_within_interval_hi"], true);

    let (_, interval, measured) = finite_fixture(0.2);
    assert!(
        measured <= interval.evolution_bound.hi + 1e-12,
        "measured {measured:.6e} exceeds interval hi {:.6e}",
        interval.evolution_bound.hi
    );

    let certificate = &pinned["artifact"]["certificate"];
    let hashes = CertificateHashes {
        operator: certificate["hashes"]["operator"].as_str().unwrap().into(),
        state: certificate["hashes"]["state"].as_str().unwrap().into(),
        basis: certificate["hashes"]["basis"].as_str().unwrap().into(),
    };
    verify_certificate(certificate, &hashes).unwrap();
}

#[test]
fn lean_matrix_matches_rust_fixture_provenance() {
    let (rust, _, _) = finite_fixture_inputs();
    let lean = lean_matrix();
    assert_eq!(lean.len(), rust.nrows(), "Lean H row count");
    for (row, cells) in lean.iter().enumerate() {
        assert_eq!(
            cells.len(),
            rust.ncols(),
            "Lean H column count in row {row}"
        );
        for (column, &(numerator, denominator, imaginary)) in cells.iter().enumerate() {
            assert_ne!(denominator, 0, "zero denominator at H[{row},{column}]");
            let expected = numerator as f64 / denominator as f64;
            let value = rust[(row, column)];
            let (actual, expected) = if imaginary {
                (value.im, expected)
            } else {
                (value.re, expected)
            };
            assert_eq!(
                actual, expected,
                "H[{row},{column}] differs: Lean {numerator}/{denominator} ({imaginary}) vs {:?}",
                value
            );
        }
    }
    assert_eq!(LEAN_SOURCE.matches("def H").count(), 1);
}

#[test]
fn matrix_enclosures_contain_the_returned_products() {
    let (h, v, _) = finite_fixture_inputs();
    let images = &h * &v;
    for (column, enclosed_column) in full_images_enclosure(&h, &v).iter().enumerate() {
        assert_eq!(enclosed_column.len(), images.nrows());
        for row in 0..images.nrows() {
            let value = images[(row, column)];
            let cell = enclosed_column[row];
            assert!(cell.re.lo <= value.re && value.re <= cell.re.hi);
            assert!(cell.im.lo <= value.im && value.im <= cell.im.hi);
        }
    }
    let generator = v.adjoint() * &h * &v;
    for (row, enclosed_row) in reduced_generator_enclosure(&h, &v).iter().enumerate() {
        assert_eq!(enclosed_row.len(), generator.ncols());
        for (column, cell) in enclosed_row.iter().enumerate() {
            let value = generator[(row, column)];
            assert!(cell.re.lo <= value.re && value.re <= cell.re.hi);
            assert!(cell.im.lo <= value.im && value.im <= cell.im.hi);
        }
    }
    let (_, interval, _) = finite_fixture(0.2);
    let point_growth = reduced_growth(&generator).max(0.0);
    assert!(
        interval.spectral_growth.hi >= point_growth,
        "Gershgorin enclosure {} is below point growth {point_growth}",
        interval.spectral_growth.hi
    );
}

#[test]
fn interval_arithmetic_rounds_outward_and_keeps_zero_exact() {
    let (a, b) = (Interval::point(0.1), Interval::point(0.2));
    let sum = a.add(b);
    assert!(sum.lo <= 0.1 + 0.2 && sum.hi >= 0.1 + 0.2);

    let wide = Interval { lo: -0.3, hi: 0.7 };
    assert!(wide.square_upper() >= 0.49);

    let zero = Interval::point(0.0).add(Interval::point(0.0));
    assert_eq!(zero, Interval::point(0.0));
}

#[test]
fn bridge_rejects_mutation_and_uncertified_promotion() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();

    let mut mutated = fixture.clone();
    mutated["artifact"]["measured_map_error"] = json!(0.0);
    assert!(matches!(
        verify_bridge(&mutated),
        Err(BridgeError::ArtifactDigest { .. })
    ));

    let mut promoted = fixture.clone();
    promoted["status"] = json!("certified");
    let promoted = bind_artifact(promoted);
    assert_eq!(
        verify_bridge(&promoted).unwrap_err(),
        BridgeError::CertifiedWithoutProof
    );

    let mut rounding = fixture.clone();
    rounding["artifact"]["rounding"]["directed"] = json!(false);
    assert!(matches!(
        verify_bridge(&rounding),
        Err(BridgeError::ArtifactDigest { .. })
    ));
}
